insert into public.products (id, slug, name, description, price, category, collection_slug, images, featured, trending, is_available, keywords, customisation_options, created_at) values
  ('p-001', 'everlasting-meadow-bouquet', 'Everlasting Meadow Bouquet', 'A hand-assembled bouquet of paper and fabric wildflowers that never wilts. Wrapped in kraft and tied with ribbon, it is meant to be kept on a shelf long after the occasion.', 1499, 'bouquets', 'bouquet-collection', '[]'::jsonb, true, true, true, array['flowers','gift','everlasting','wildflower']::text[], '[{"id":"ribbon","label":"Ribbon colour","type":"select","required":false,"choices":["Ivory","Sage","Antique gold","Evergreen"]}]'::jsonb, '2026-09-12'),
  ('p-002', 'blush-peony-bouquet', 'Blush Peony Bouquet', 'Layered peonies made petal by petal, softly tinted and arranged with eucalyptus-style greenery. A generous, full bouquet for the big moments.', 1899, 'bouquets', 'bouquet-collection', '[]'::jsonb, true, false, true, array['peony','flowers','anniversary','gift']::text[], '[{"id":"ribbon","label":"Ribbon colour","type":"select","required":false,"choices":["Ivory","Sage","Antique gold","Evergreen"]}]'::jsonb, '2026-10-02'),
  ('p-003', 'wild-fern-and-sage-posy', 'Wild Fern & Sage Posy', 'A small, green-toned posy of ferns and dried-look sprigs. Sits happily in a glass jar on a desk or windowsill.', 899, 'bouquets', 'handmade-favourites', '[]'::jsonb, false, true, true, array['posy','fern','green','desk']::text[], '[]'::jsonb, '2026-08-20'),
  ('p-004', 'pocket-garden-keychain', 'Pocket Garden Keychain', 'A tiny handmade garden you can carry: miniature blooms and a leaf charm on a sturdy gold-tone ring.', 349, 'keychains', 'little-things-big-smiles', '[]'::jsonb, true, true, true, array['keyring','flowers','charm','small gift']::text[], '[]'::jsonb, '2026-09-28'),
  ('p-005', 'tiny-bloom-charm', 'Tiny Bloom Charm', 'A single handmade bloom on a clasp, small enough to hang from a bag zip, a phone or a set of keys.', 249, 'keychains', 'little-things-big-smiles', '[]'::jsonb, false, false, true, array['charm','bag charm','small gift']::text[], '[{"id":"colour","label":"Bloom colour","type":"select","required":true,"choices":["Ivory","Blush","Sage","Antique gold"]}]'::jsonb, '2026-07-30'),
  ('p-006', 'initial-letter-keychain', 'Initial Letter Keychain', 'Your initial, shaped by hand and finished with a small floral detail. A thoughtful, personal little gift.', 399, 'keychains', 'personalised-keepsakes', '[]'::jsonb, true, false, true, array['letter','name','personalised','custom']::text[], '[{"id":"initial","label":"Initial","type":"text","required":true,"placeholder":"e.g. A","maxLength":1},{"id":"charm","label":"Charm colour","type":"select","required":false,"choices":["Sage","Ivory","Antique gold"]}]'::jsonb, '2026-10-10'),
  ('p-007', 'name-frame-keepsake', 'Name Frame Keepsake', 'A small framed piece with a name or short word lettered and decorated by hand. A keepsake for a new baby, a birthday or a new home.', 1299, 'personalised-gifts', 'personalised-keepsakes', '[]'::jsonb, true, true, true, array['name','frame','baby','birthday','custom']::text[], '[{"id":"name","label":"Name or word","type":"text","required":true,"placeholder":"e.g. Aarohi","maxLength":24},{"id":"frame","label":"Frame colour","type":"select","required":false,"choices":["Sage","Ivory","Evergreen"]}]'::jsonb, '2026-10-18'),
  ('p-008', 'hand-bound-memory-box', 'Hand-Bound Memory Box', 'A keepsake box covered in handmade paper, with space inside for letters, photographs and small treasures.', 1799, 'personalised-gifts', 'personalised-keepsakes', '[]'::jsonb, false, false, true, array['box','memories','paper','wedding','gift']::text[], '[{"id":"title","label":"Title for the lid","type":"text","required":false,"placeholder":"e.g. Our first year","maxLength":30},{"id":"ribbon","label":"Ribbon colour","type":"select","required":false,"choices":["Ivory","Sage","Antique gold","Evergreen"]}]'::jsonb, '2026-09-05'),
  ('p-009', 'the-slow-mornings-zine', 'The Slow Mornings Zine', 'A small hand-stitched magazine of pressed botanicals, short notes and quiet illustrations for unhurried mornings.', 599, 'magazines', 'magazine-collection', '[]'::jsonb, true, false, true, array['zine','magazine','journal','paper','reading']::text[], '[]'::jsonb, '2026-10-22'),
  ('p-010', 'pressed-flowers-journal-magazine', 'Pressed Flowers Journal Magazine', 'A hand-bound issue with real pressed flowers on every spread and space to write or sketch in between.', 749, 'magazines', 'magazine-collection', '[]'::jsonb, false, true, true, array['pressed flowers','journal','magazine','diary']::text[], '[]'::jsonb, '2026-08-14'),
  ('p-011', 'handmade-paper-bookmark-set', 'Handmade Paper Bookmark Set', 'A set of three bookmarks made from handmade paper, each with a small dried-leaf detail and a silk tassel.', 299, 'other-crafts', 'handmade-favourites', '[]'::jsonb, false, false, true, array['bookmark','paper','reading','set of 3']::text[], '[]'::jsonb, '2026-07-18'),
