-- Seed: your original sample products and collections (generated by scripts/generate-seed.mjs).
-- Run AFTER 01_schema.sql. Safe to re-run (it updates rows with the same id).
-- Products have no photos yet: the shop shows a tidy placeholder until you upload real ones in /admin.

on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description,
  theme = excluded.theme, sort_order = excluded.sort_order;

on conflict (id) do update set slug = excluded.slug, name = excluded.name, description = excluded.description,
  price = excluded.price, category = excluded.category, collection_slug = excluded.collection_slug,
  featured = excluded.featured, trending = excluded.trending, is_available = excluded.is_available,
  keywords = excluded.keywords, customisation_options = excluded.customisation_options;
